type Reply<'a>=OriginalEffectReply<'a,RetainedCloneStep,OriginalRetirementFailure>;
type Complete<'a>=OriginalEffectReplyComplete<'a,RetainedCloneStep,OriginalRetirementFailure>;
type Slots<M,T=u64>=NativeSharedSlots<T,<M as Mode<T>>::Output>;
fn shared_law()->serde_json::Value{serde_json::from_str(include_str!("owner.json")).unwrap()}
fn fixed(copy:usize)->RetirementDemand{RetirementDemand{copy_bytes:copy,depth:1,..Default::default()}}
fn string_release_demand(value:&Option<String>)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:size_of::<Option<String>>()+size_of::<String>(),release_bytes:value.as_ref().ok_or_else(||ValueError::invariant("original String is absent"))?.capacity(),depth:1,..Default::default()})}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes,..Default::default()}}
trait Mode<T:RetireOwned+Sync=u64>:Send+Sync+'static{
 type Output:RetireOwned+Sync;
 fn capture<'a>(slots:&mut Slots<Self,T>,input:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>where Self:Sized;
 fn take<'a>(slots:&mut Slots<Self,T>,output:&mut Option<Self::Output>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>where Self:Sized;
 fn demand(slots:&Slots<Self,T>)->Result<RetirementDemand,ValueError>where Self:Sized;
 fn work(slots:&Slots<Self,T>)->Result<u64,ValueError>where Self:Sized;
 fn advance(slots:&mut Slots<Self,T>,control:&mut NativeDecodeControl<'_>)->Result<NativeReceivingEffectState,ValueError>where Self:Sized;
 fn take_demand(slots:&Slots<Self,T>)->Result<RetirementDemand,ValueError>where Self:Sized;
 fn value(output:&Self::Output)->&T;
 fn consume_demand(output:&Option<Self::Output>,owner:&Option<SharedOriginal<T>>)->Result<(RetirementDemand,u64),ValueError>;
 fn consume<'a>(output:&mut Option<Self::Output>,owner:&mut Option<SharedOriginal<T>>,value:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>;
}
struct IssuedMode;struct SealedMode;
macro_rules! shared_mode{($mode:ident,$out:ident)=>{
 impl<T:RetireOwned+Sync> Mode<T> for $mode{
  type Output=$out<T>;
  fn capture<'a>(slots:&mut Slots<Self,T>,input:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>{slots.capture(input,effect,reply)}
  fn take<'a>(slots:&mut Slots<Self,T>,output:&mut Option<Self::Output>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>{slots.take(output,effect,reply)}
  fn demand(slots:&Slots<Self,T>)->Result<RetirementDemand,ValueError>{slots.demand()}
  fn work(slots:&Slots<Self,T>)->Result<u64,ValueError>{slots.advance_work_demand()}
  fn advance(slots:&mut Slots<Self,T>,control:&mut NativeDecodeControl<'_>)->Result<NativeReceivingEffectState,ValueError>{slots.advance(control)}
  fn take_demand(slots:&Slots<Self,T>)->Result<RetirementDemand,ValueError>{slots.take_demand()}
  shared_mode!(@$mode);
 }
};(@IssuedMode)=>{
 fn value(output:&Self::Output)->&T{output.get()}
 fn consume_demand(output:&Option<Self::Output>,owner:&Option<SharedOriginal<T>>)->Result<(RetirementDemand,u64),ValueError>{if let Some(output)=output{return if output.terminal_is_empty(){Ok((fixed(size_of::<Option<Self::Output>>()),1))}else{Ok((output.retire_into_demand()?,output.retire_work_demand()?))}}let owner=owner.as_ref().unwrap();if owner.terminal_is_empty(){Ok((fixed(size_of::<Option<SharedOriginal<T>>>()),1))}else{Ok((owner.take_value_demand()?,owner.take_value_work_demand()?))}}
 fn consume<'a>(output:&mut Option<Self::Output>,owner:&mut Option<SharedOriginal<T>>,value:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>{if let Some(alias)=output.as_mut(){if !alias.terminal_is_empty(){return alias.retire_into(owner,effect,reply)}let(d,_)=Self::consume_demand(output,owner)?;assert!(effect.performed(1)?);output.take();return Ok(reply.complete(Ok(RetainedCloneStep::Progress(receipt(d)))))}if owner.as_ref().unwrap().terminal_is_empty(){let(d,_)=Self::consume_demand(output,owner)?;assert!(effect.performed(1)?);owner.take();return Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(d)))))}let turn=owner.as_mut().unwrap().take_value_step(value,effect);Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))}
};(@SealedMode)=>{
 fn value(output:&Self::Output)->&T{output.get()}
 fn consume_demand(output:&Option<Self::Output>,owner:&Option<SharedOriginal<T>>)->Result<(RetirementDemand,u64),ValueError>{if let Some(output)=output{return Ok((output.original_election_demand()?,output.original_election_work_demand()?))}let owner=owner.as_ref().unwrap();if owner.terminal_is_empty(){Ok((fixed(size_of::<Option<SharedOriginal<T>>>()),1))}else{Ok((owner.take_value_demand()?,owner.take_value_work_demand()?))}}
 fn consume<'a>(output:&mut Option<Self::Output>,owner:&mut Option<SharedOriginal<T>>,value:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>{if output.is_some(){let turn=SealedShared::try_owner_into(output,owner,effect);return Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))}if owner.as_ref().unwrap().terminal_is_empty(){let(d,_)=Self::consume_demand(output,owner)?;assert!(effect.performed(1)?);owner.take();return Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(d)))))}let turn=owner.as_mut().unwrap().take_value_step(value,effect);Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))}
}}
shared_mode!(IssuedMode,SharedOriginalStorage);
shared_mode!(SealedMode,SealedShared);
