enum Command<'a,M:Mode<T>,T:RetireOwned+Sync=u64>{AckAdvance(&'a mut Slots<M,T>,semio_framework_value_native_decoding::NativeReceivingSuccessIdentity,&'a mut Option<RetainedCloneStep>),CloseAdvance(&'a mut Slots<M,T>,semio_framework_value_native_decoding::NativeReceivingSuccessIdentity),FrameResult(&'a mut NativeReceivingEffect<OriginalRetirementFailure>,&'a mut Option<NativeReceivingEffectOutcome<OriginalRetirementFailure>>),AdvanceResultThenUnwind(&'a mut Slots<M,T>,&'a mut Option<NativeReceivingEffectOutcome<OriginalRetirementFailure>>,&'a mut usize),AdvanceResult(&'a mut Slots<M,T>,&'a mut Option<NativeReceivingEffectOutcome<OriginalRetirementFailure>>),ReleaseString(&'a mut Option<String>),Capture(&'a mut Slots<M,T>,&'a mut Option<T>),Take(&'a mut Slots<M,T>,&'a mut Option<M::Output>),Close(&'a mut Slots<M,T>),Reclaim(&'a mut Slots<M,T>,&'a mut Option<T>),Consume(&'a mut Option<M::Output>,&'a mut Option<SharedOriginal<T>>,&'a mut Option<T>)}
struct CommandContext<'a,M:Mode<T>,T:RetireOwned+Sync=u64>{turn:&'a OriginalSourceTurn,command:Command<'a,M,T>}
struct Commands<M:Mode<T>,T:RetireOwned+Sync=u64>{source:Arc<OriginalSourceTurnIssuer>,mode:PhantomData<(M,T)>}
impl<M:Mode<T>,T:RetireOwned+Sync> OriginalEffectProducer for Commands<M,T>{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'turn,'source>=CommandContext<'turn,M,T>where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c.turn).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.turn.identity())}
 fn receive<'a,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>where 'source:'turn{assert!(effect.construction_action().is_some(),"actual receiving effect must retain its granted construction action");match &mut c.command{Command::AckAdvance(slots,identity,output)=>slots.acknowledge_advance_success_into(*identity,output,effect,reply),Command::CloseAdvance(slots,identity)=>slots.close_advance_success_into(*identity,effect,reply),Command::FrameResult(frame,output)=>frame.transfer_into(output,effect,reply),Command::AdvanceResultThenUnwind(slots,output,calls)=>{let answer=slots.take_advance_result(output,effect,reply)?;if output.is_some(){**calls+=1;assert!(answer.is_recorded());panic!("actual shared outcome and its original metadata reply are already recorded")}Ok(answer)},Command::AdvanceResult(slots,output)=>slots.take_advance_result(output,effect,reply),Command::ReleaseString(source)=>{let d=string_release_demand(source)?;if !retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}assert!(effect.performed(1)?);drop(source.take());Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(d)))))},Command::Capture(slots,input)=>M::capture(slots,input,effect,reply),Command::Take(slots,output)=>M::take(slots,output,effect,reply),Command::Close(slots)=>slots.close_step(4096,effect,reply),Command::Reclaim(slots,output)=>slots.reclaim_input(output,effect,reply),Command::Consume(output,owner,value)=>M::consume(output,owner,value,effect,reply)}}
 fn recover<'a,'turn,'source>(&mut self,c:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'a>)->Result<Complete<'a>,ValueError>where 'source:'turn{self.receive(c,effect,reply)}
}
fn command<M:Mode<T>,T:RetireOwned+Sync>(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,producer:&mut OriginalEffectAuthority<Commands<M,T>>,d:RetirementDemand,maximum_work:u64,operation:Command<'_,M,T>)->NativeReceivingEffectPoll<OriginalRetirementFailure>{
 bank.run_with_turn(native,|turn,native|{let mut context=CommandContext{turn,command:operation};native.receive_original_effect(d,maximum_work,frame,producer,|_,effect,producer,action|producer.drive(&mut context,effect,action))}).unwrap_or_else(|error|panic!("original command in phase {:?}: {error:?}",frame.phase()))

}
fn command_retained<M:Mode<T>,T:RetireOwned+Sync>(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,producer:&mut OriginalEffectAuthority<Commands<M,T>>,d:RetirementDemand,maximum_work:u64,operation:Command<'_,M,T>)->NativeReceivingEffectState{bank.run_with_turn(native,|turn,native|{let mut context=CommandContext{turn,command:operation};native.receive_original_effect_retained(d,maximum_work,frame,producer,&mut context)}).unwrap()}
fn complete(poll:NativeReceivingEffectPoll<OriginalRetirementFailure>)->RetainedWorkOutcome<RetainedCloneStep,NativeReceivingEffectFailure<OriginalRetirementFailure>>{match poll{NativeReceivingEffectPoll::Complete(turn)=>turn,NativeReceivingEffectPoll::Pending{..}=>panic!("synchronous Source fixture remained pending")}}
fn constructor<M:Mode>(interrupt:bool){
 let mut bank=Bank::new(interrupt);let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<20,&mut observer);let mut frame=NativeReceivingEffect::default();let mut producer=OriginalEffectAuthority::new(Commands::<M>{source:bank.source.clone(),mode:PhantomData});let mut slots=Slots::<M>::default();let mut input=Some(73);let d=Slots::<M>::capture_demand().unwrap();let capture_work=slots.capture_work_demand(&input).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,capture_work,Command::Capture(&mut slots,&mut input))).result.unwrap();assert!(input.is_none());let mut replacement=Some(91);let rejected=complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Capture(&mut slots,&mut replacement)));assert!(rejected.result.is_err());assert_eq!(replacement,Some(91));let mut slots=Box::new(slots);assert_eq!(slots.input(),Some(&73));
 if interrupt{let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(&mut native,|native|M::advance(&mut slots,native))));assert!(interrupted.is_err());assert!(slots.advance_pending());assert!(!slots.output_ready())}
 for _ in 0..16{if slots.output_ready(){break}let turn=advance_paid(&mut bank,&mut native,&mut frame,&mut producer,&mut slots).successful();turn.result.unwrap();}
 assert!(slots.output_ready());let mut output=None;let d=M::take_demand(&slots).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Take(&mut slots,&mut output))).result.unwrap();assert!(!slots.terminal_is_empty());assert_eq!(*M::value(output.as_ref().unwrap()),73);for _ in 0..4{if slots.terminal_is_empty(){break}let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();}assert!(slots.terminal_is_empty());let(mut owner,mut value)=(None,None);
 for _ in 0..8{if output.is_none()&&owner.is_none(){break}let(d,work)=M::consume_demand(&output,&owner).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Consume(&mut output,&mut owner,&mut value))).result.unwrap();}
 assert_eq!(value,Some(73));assert!(output.is_none()&&owner.is_none());let wallet=bank.wallet.lock().unwrap();assert_eq!(256-wallet.fuel,native.actual_work());assert!(wallet.partials>0);assert_eq!(wallet.spent.retained_capacity_bytes,wallet.spent.released_bytes);drop(wallet);assert!(producer.into_producer().is_ok());
}
