#[test]fn actual_shared_capture_refuses_an_effect_without_its_original_source(){
 struct Unbound;impl OriginalWorkRecipient for Unbound{type Context<'turn,'source>=()where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}fn admits<'a,'turn,'source>(&mut self,_:&mut (),reply:OriginalWorkQuote<'a>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'a>where 'source:'turn{reply.complete(Ok(observed.checked_add(additional).is_some_and(|total|total<=2)))}fn settle_partial<'a,'turn,'source>(&mut self,_:&mut (),reply:OriginalWorkPartialCheck<'a>)->OriginalWorkPartialCheckComplete<'a>where 'source:'turn{reply.complete(Ok(()))}fn recover_partial<'a,'turn,'source>(&mut self,_:&mut (),reply:OriginalWorkPartialCheck<'a>)->OriginalWorkPartialCheckComplete<'a>where 'source:'turn{reply.pending()}}
 let mut authority=OriginalWorkAuthority::new(Unbound);authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut original=OriginalWork{state:OriginalWorkState::fresh(),recipient:Some(&mut loan)};let mut work=OriginalWorkBorrow::new(&mut original);let mut action=None;assert_eq!(work.prepare(2,&mut action).unwrap(),Some(true));let(mut receipt,mut claim)=(None,None);let mut slots=Slots::<IssuedMode>::default();let mut input=Some(73);let d=Slots::<IssuedMode>::capture_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()};let mut actual=None;let mut scope=work.performed_scope(action,&mut receipt,&mut claim).unwrap();let mut effect=scope.effect(grant,2,&mut actual).unwrap();assert_eq!(effect.work_source_turn(),None);let mut answer=std::mem::ManuallyDrop::new(None);let reply=OriginalEffectReply::borrow(&mut answer).unwrap();let complete=slots.capture(&mut input,&mut effect,reply).unwrap();drop(complete);assert_eq!(answer.as_ref().unwrap().is_ok(),shared_law()["admission"]["unboundAccepted"].as_bool().unwrap());assert_eq!(input,Some(73));assert!(slots.terminal_is_empty());drop(effect);drop(scope);assert_eq!(claim.take().unwrap().unwrap(),0);work.cancel(&mut action).unwrap();Ok::<_,ValueError>(())}).unwrap().unwrap();
}

