struct Advanced{ready_work:u128,outcome:NativeReceivingEffectOutcome<OriginalRetirementFailure>,transfer:NativeReceivingEffectOutcome<OriginalRetirementFailure>}
impl Advanced{fn observed_work(&self)->u128{self.ready_work+self.outcome.work}fn successful(self)->NativeReceivingEffectOutcome<OriginalRetirementFailure>{self.transfer.result.unwrap();self.outcome}}
fn advance_paid<M:Mode<T>,T:RetireOwned+Sync>(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,producer:&mut OriginalEffectAuthority<Commands<M,T>>,slots:&mut Slots<M,T>)->Advanced{
 let state=bank.run(native,|native|M::advance(slots,native)).unwrap();let NativeReceivingEffectState::Ready{work:ready_work}=state else{panic!("synchronous native shared constructor must settle")};assert!(slots.advance_result_ready());assert!(!slots.advance_pending());assert!(!slots.output_ready());let demand=slots.advance_result_demand().unwrap();let work=slots.advance_result_work_demand();let mut outcome=None;let transfer=complete(command(bank,native,frame,producer,demand,work,Command::AdvanceResult(slots,&mut outcome)));let outcome=outcome.take().expect("funded original shared result is resident");assert!(!slots.advance_result_ready());Advanced{ready_work,outcome,transfer}
}

fn advance_paid_rejected<M:Mode<T>,T:RetireOwned+Sync>(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,producer:&mut OriginalEffectAuthority<Commands<M,T>>,slots:&mut Slots<M,T>,retry:&serde_json::Value)->Advanced{
 let state=bank.run(native,|native|M::advance(slots,native)).unwrap();let NativeReceivingEffectState::Pending{work:pending_work}=state else{panic!("original physical refusal must remain pending")};let(spent,fuel,posts)={let wallet=bank.wallet.lock().unwrap();(wallet.spent,wallet.fuel,wallet.post_calls)};let NativeReceivingEffectState::Pending{work:repeat}=bank.run(native,|native|M::advance(slots,native)).unwrap()else{panic!("original refusal lost Pending")};assert_eq!(repeat,u128::from(retry["work"].as_u64().unwrap()));{let wallet=bank.wallet.lock().unwrap();assert_eq!(wallet.post_calls-posts,retry["additionalPosts"].as_u64().unwrap() as usize);assert_eq!(wallet.spent,spent);assert_eq!(fuel-wallet.fuel,u128::from(retry["additionalFuel"].as_u64().unwrap()))}assert!(!slots.advance_result_ready());bank.wallet.lock().unwrap().reject=false;let mut payout=receipt_payout::ReceiptPayout::default();assert!(payout.settle(bank,native,slots).unwrap());let NativeReceivingEffectState::Ready{work:resumed_work}=bank.run(native,|native|M::advance(slots,native)).unwrap()else{panic!("original refused receipt remains pending after paid recovery")};let ready_work=pending_work.checked_add(resumed_work).expect("actual reported work overflow");assert!(slots.advance_result_ready());let demand=slots.advance_result_demand().unwrap();let work=slots.advance_result_work_demand();let mut outcome=None;bank.wallet.lock().unwrap().reject=true;let pending=command_retained(bank,native,frame,producer,demand,work,Command::AdvanceResult(slots,&mut outcome));assert!(matches!(pending,NativeReceivingEffectState::Pending{..}));let(spent,fuel,posts)={let wallet=bank.wallet.lock().unwrap();(wallet.spent,wallet.fuel,wallet.post_calls)};let pending=command_retained(bank,native,frame,producer,demand,work,Command::AdvanceResult(slots,&mut outcome));let NativeReceivingEffectState::Pending{work:repeat}=pending else{panic!("original metadata refusal lost Pending")};assert_eq!(repeat,u128::from(retry["work"].as_u64().unwrap()));{let wallet=bank.wallet.lock().unwrap();assert_eq!(wallet.post_calls-posts,retry["additionalPosts"].as_u64().unwrap() as usize);assert_eq!(wallet.spent,spent);assert_eq!(fuel-wallet.fuel,u128::from(retry["additionalFuel"].as_u64().unwrap()))}bank.wallet.lock().unwrap().reject=false;let mut payout=receipt_payout::ReceiptPayout::default();assert!(payout.settle(bank,native,frame).unwrap());assert!(matches!(command_retained(bank,native,frame,producer,demand,work,Command::AdvanceResult(slots,&mut outcome)),NativeReceivingEffectState::Ready{..}));let transfer_demand=frame.transfer_demand().unwrap();let mut payment_frame=NativeReceivingEffect::default();let mut transfer=None;let paid=complete(command(bank,native,&mut payment_frame,producer,transfer_demand,1,Command::FrameResult(frame,&mut transfer)));paid.result.unwrap();let transfer=transfer.take().expect("paid original transfer outcome retained");let outcome=outcome.take().expect("funded original shared result is resident");assert!(!slots.advance_result_ready());bank.wallet.lock().unwrap().reject=true;Advanced{ready_work,outcome,transfer}
}

